14	package com.facebook.presto.hive.security;
15	
16	import com.facebook.presto.plugin.base.security.FileBasedAccessControlModule;
17	import com.facebook.presto.plugin.base.security.ReadOnlySecurityModule;
18	import com.google.inject.Binder;
19	import com.google.inject.Module;
20	import io.airlift.configuration.AbstractConfigurationAwareModule;
21	
22	import static io.airlift.configuration.ConditionalModule.installModuleIf;
23	
24	public class HiveSecurityModule
25	        extends AbstractConfigurationAwareModule
26	{
27	    @Override
28	    protected void setup(Binder binder)
29	    {
30	        bindSecurityModule("legacy", new LegacySecurityModule());
31	        bindSecurityModule("file", new FileBasedAccessControlModule());
32	        bindSecurityModule("read-only", new ReadOnlySecurityModule());
33	        bindSecurityModule("sql-standard", new SqlStandardSecurityModule());
34	    }
35	
36	    private void bindSecurityModule(String name, Module module)
37	    {
38	        install(installModuleIf(
39	                SecurityConfig.class,
40	                security -> name.equalsIgnoreCase(security.getSecuritySystem()),
41	                module));
42	    }
